import bpy, json, base64, os, tempfile
if 'responder' not in globals():
    def responder(d): print(json.dumps(d))
sc = bpy.context.window.scene if bpy.context.window else bpy.context.scene
info = {"escena": sc.name, "escenas": [s.name for s in bpy.data.scenes], "cuadro": sc.frame_current,
        "rango": [sc.frame_start, sc.frame_end], "fps": sc.render.fps,
        "camara": sc.camera.name if sc.camera else None,
        "marcadores": sorted([[m.frame, m.name, m.camera.name if m.camera else None] for m in sc.timeline_markers]),
        "res": [sc.render.resolution_x, sc.render.resolution_y, sc.render.resolution_percentage]}
areas = []
for w in bpy.context.window_manager.windows:
    for a in w.screen.areas:
        if a.type == 'VIEW_3D':
            sp = a.spaces.active
            areas.append({"shading": sp.shading.type, "color": getattr(sp.shading, "color_type", None),
                          "persp": sp.region_3d.view_perspective})
info["viewports"] = areas
# cámaras: claves de lente y posición (lectura, sin mover el cuadro)
cams = []
for ob in sc.objects:
    if ob.type == 'CAMERA':
        c = {"nombre": ob.name, "lens": ob.data.lens, "claves_obj": [], "claves_lente": []}
        if ob.animation_data and ob.animation_data.action:
            fr = sorted({int(k.co[0]) for fc in ob.animation_data.action.fcurves for k in fc.keyframe_points})
            c["claves_obj"] = fr
        if ob.data.animation_data and ob.data.animation_data.action:
            for fc in ob.data.animation_data.action.fcurves:
                c["claves_lente"] += [[int(k.co[0]), round(k.co[1], 2), fc.data_path] for k in fc.keyframe_points]
        cams.append(c)
info["camaras"] = cams
# captura del viewport en el cuadro actual (OpenGL, con la vista que ya tiene); se restaura el porcentaje
estado_pct = sc.render.resolution_percentage
png = None
try:
    ctx = None
    for w in bpy.context.window_manager.windows:
        for a in w.screen.areas:
            if a.type == 'VIEW_3D':
                reg = [r for r in a.regions if r.type == 'WINDOW'][0]
                ctx = {"window": w, "screen": w.screen, "area": a, "region": reg, "scene": sc}
                break
        if ctx: break
    sc.render.resolution_percentage = 40
    bpy.ops.render.opengl(ctx, write_still=False, view_context=False)
    ruta = os.path.join(tempfile.gettempdir(), "captura_actual_implante.png")
    bpy.data.images["Render Result"].save_render(ruta)
    png = base64.b64encode(open(ruta, "rb").read()).decode()
except Exception as e:
    info["error_captura"] = repr(e)
finally:
    sc.render.resolution_percentage = estado_pct
responder({"info": info, "png": png})
